use crate::vnc::engine::PixelFormat;

type ImageData = Vec<u8>;

/// A rect where the image should be updated
#[derive(Debug, Clone, Copy)]
pub struct Rect {
    pub x: u16,
    pub y: u16,
    pub width: u16,
    pub height: u16,
}

/// Resolution format to resize window
#[derive(Debug, Clone)]
pub struct Screen {
    pub width: u16,
    pub height: u16,
}

impl From<(u16, u16)> for Screen {
    fn from(tuple: (u16, u16)) -> Self {
        Self {
            width: tuple.0,
            height: tuple.1,
        }
    }
}

type SrcRect = Rect;
type DstRect = Rect;

/// Events generated by the [crate::vnc::engine::VncClient]
///
#[non_exhaustive]
#[derive(Debug, Clone)]
pub enum VncEvent {
    /// Tell the client how to display the images
    ///
    /// ```no_compile
    /// if let VncEvent::SetResolution(resolution) = event {
    ///     window.resize(screen.width, screen.height);
    /// }
    /// ```
    ///
    /// Note that this event may be recived multiple times
    ///
    /// If the [crate::vnc::engine::VncEncoding::DesktopSizePseudo] is set
    ///
    SetResolution(Screen),
    /// Negotiated layout or resize result. Same-size updates preserve pixels.
    /// Never answer this announcement with an unconditional full refresh.
    DesktopUpdate(crate::vnc::engine::DesktopUpdate),
    /// If the connector doesn't call `set_pixel_format` method
    ///
    /// The engine will generate a [VncEvent::SetPixelFormat] to let the window know how to render image
    ///
    SetPixelFormat(PixelFormat),
    /// Raw image data in the order followed by informed PixelFormat
    ///
    RawImage(Rect, ImageData),
    /// Copy image data from the second rect to the first
    ///
    Copy(DstRect, SrcRect),
    /// A jpeg image if using Tight encoding,
    ///
    /// Encoding the bytes with base64 and render it with "<img src=data:image/jpeg;base64,.../>",
    ///
    JpegImage(Rect, ImageData),

    // PngImage(Rect, ImageData),
    /// Will be generated if [crate::vnc::engine::VncEncoding::CursorPseudo] is set
    ///
    /// According to [RFC6143, section-7.8.1](https://www.rfc-editor.org/rfc/rfc6143.html#section-7.8.1)
    ///
    SetCursor(Rect, ImageData),
    /// Just ring a bell
    ///
    Bell,
    /// The server's clipboard changed: the text, UTF-8 through the extended clipboard (with LF
    /// line ends), or Latin-1 through plain ServerCutText (RFC 6143, 7.6.4), here as a String.
    Text(String),
    /// A rectangle of the current update starts: where, and its encoding (pseudo ones too). Its
    /// pixels follow as [VncEvent::RawImage], [VncEvent::Copy] or [VncEvent::SetCursor].
    /// Only with [crate::vnc::engine::connect] (the vnc-rs connector keeps its old events).
    Rectangle(Rect, crate::vnc::engine::VncEncoding),
    /// The end of one FramebufferUpdate: the picture is consistent here (a good moment to show it).
    /// Only with [crate::vnc::engine::connect].
    UpdateDone,
    /// The server confirmed QEMU extended key events: [X11Event::ScancodeKey] now sends scancodes.
    QemuKeyEvents,
    /// A rectangle of one colour (in the pixel format asked for): Tight's fill, without a
    /// picture of it. Only with [crate::vnc::engine::connect] and no [DrawTarget].
    Fill(Rect, [u8; 4]),
    /// Continuous updates went on (true: the server sends changes without a request for each,
    /// so the app stops asking) or off (a pause, or the server stopped them).
    ContinuousUpdates(bool),
    /// If any unexpected error happens in the async process routines
    /// This event will propagate the error to the current context
    Error(String),
}

/// X11 keyboard event to notify the server
///
/// Referring to [RFC6143, section-7.5.4](https://www.rfc-editor.org/rfc/rfc6143.html#section-7.5.4)
///
#[derive(Debug, Clone)]
pub struct ClientKeyEvent {
    pub keycode: u32,
    pub down: bool,
}

impl From<(u32, bool)> for ClientKeyEvent {
    fn from(tuple: (u32, bool)) -> Self {
        Self {
            keycode: tuple.0,
            down: tuple.1,
        }
    }
}

/// X11 mouse event to notify the server
///
/// Referring to [RFC6143, seciont-7.5.5](https://www.rfc-editor.org/rfc/rfc6143.html#section-7.5.5)
///
#[derive(Debug, Clone)]
pub struct ClientMouseEvent {
    pub position_x: u16,
    pub position_y: u16,
    pub bottons: u8,
}

impl From<(u16, u16, u8)> for ClientMouseEvent {
    fn from(tuple: (u16, u16, u8)) -> Self {
        Self {
            position_x: tuple.0,
            position_y: tuple.1,
            bottons: tuple.2,
        }
    }
}

/// Client-side event which used to ask the engine send some command to the vnc server
///
#[non_exhaustive]
#[derive(Debug, Clone)]
pub enum X11Event {
    /// Require an incremental frame update
    ///
    Refresh,
    /// Require a full (non-incremental) frame update.
    /// Forces the server to send the entire framebuffer, useful after
    /// CursorPseudo is negotiated to clear cursor ghosts from the framebuffer.
    FullRefresh,
    /// Key down/up
    ///
    KeyEvent(ClientKeyEvent),
    /// Mouse move/up/down/scroll
    ///
    PointerEvent(ClientMouseEvent),
    /// Send text to the server's clipboard: UTF-8 through the extended clipboard when the server
    /// has it, else Latin-1 (other characters become '?').
    CopyText(String),
    /// A key with its keysym and its XT scancode (extended keys with 0x80 set: 0xE0 0x4D is
    /// 0xCD): QEMU's extended key event once the server confirmed it ([VncEvent::QemuKeyEvents]),
    /// else a plain key event with the keysym.
    ScancodeKey { keysym: u32, scancode: u32, down: bool },
    /// Stop updates (the app is hidden): continuous updates off; the app sends no requests
    /// meanwhile ([crate::vnc::engine::VncClient::wants_requests] says so).
    Pause,
    /// Updates again, with the whole screen at once: continuous updates on again when the
    /// server has them, and a full (non-incremental) request.
    Resume,
}

/// Where the engine draws when the app gives it one ([crate::vnc::engine::ConnectOptions::draw]):
/// pixels go straight into the app's picture from the decoder, instead of as events through the
/// event queue (no copy per rectangle into an event, no wait on the app's loop). Rectangles are
/// in the pixel format asked for; the fourth byte of each pixel may be the server's padding.
/// Called from the engine's decoding task, in the order the server sent them.
pub trait DrawTarget: Send + Sync {
    /// A new framebuffer size (the first one, from ServerInit, before any pixels).
    fn resize(&self, width: u16, height: u16);
    /// A rectangle of one colour.
    fn fill(&self, rect: &Rect, pixel: [u8; 4]);
    /// A rectangle's pixels, `rect.width * 4` bytes a row.
    fn put(&self, rect: &Rect, pixels: &[u8]);
    /// CopyRect: from [src] to [dst] (they may overlap).
    fn copy(&self, dst: &Rect, src: &Rect);
}
